mapper.select:
select distinct a.project_name, a.buy_user as buy_user_name , a.buy_budget_money, a.open_bid_time, c.unicom_type, a.competition_condition, a.result as bid_result, a.bid_body, a.project_type, a.sign_money, a.expected_main_operating_amount, a.ict_profit, a.is_framework_contract, a.contract_time, c.opp_code, c.opp_name, f.dept_name as opp_dept_name, d.nick_name as opp_manager, g.dept_name as main_support_dept_name, if(h.member_id=e.user_id,'主责支撑经理','支撑经理') as support_role, i.nick_name as support_manager, l.tdry as support_team, k.hours as work_days, x.contribution, x.grgxed as personal_contribution_amount
from topp_bid_new a inner join topp_bid_new_score b on a.id=b.topp_bid_new_id inner join topp_opportunity c on c.id_=b.opportunity_code left join zqzt_sys_user d on c.cust_manager_id=d.user_id left join zqzt_sys_user e on c.designer =e.user_id left join zqzt_sys_dept f on d.dept_id=f.dept_id left join zqzt_sys_dept g on e.dept_id=g.dept_id left join topp_member h on h.project_id = c.id_ left join zqzt_sys_user i on h.member_id=i.user_id left join (select aa.info_id,aa.actor_,sum(support_hours) hours from tcomm_task aa where aa.actor_ is not null group by aa.info_id,aa.actor_)k on k.info_id=c.id_ and h.member_id=k.actor_ left join (select project_id, GROUP_CONCAT( CONCAT_WS( ',', name_) SEPARATOR ';' ) as tdry from (select distinct project_id,name_ from topp_member aa where aa.member_role = 'member_role_zcjl' )ss group by project_id )l on l.project_id =c.id_ left join (select a.id,any_value(name_) as name_ts,b.contribution, a.sign_money * b.contribution/100 as grgxed from topp_bid_new a inner join topp_bid_new_score b on a.id=b.topp_bid_new_id inner join topp_member c on b.name=c.name_ and c.project_id =b.opportunity_code ) x on a.id=x.id and h.name_=x.name_ts where a.is_sign='0' and h.member_role = 'member_role_zcjl' and i.dept_id in( select dept_id from zqzt_sys_dept where dept_id = #{deptId} union select t.dept_id from (select * from zqzt_sys_dept where parent_id is not null) t, (select @parent_id := #{deptId}) pd where FIND_IN_SET(parent_id,@parent_id) > 0 and @parent_id := CONCAT(@parent_id,',',dept_id) )
and a.buy_budget_money >= #{minCgAmount}
and a.buy_budget_money < #{maxCgAmount}
and a.sign_money >= #{minYjAmount}
and a.sign_money < #{maxYjAmount}
and c.expect_count_money >= #{minYjAmount}
and c.expect_count_money < #{maxYjAmount}
and a.bid_body in
#{item}
and a.competition_condition in
#{item}
and a.project_type in
#{item}
and a.result = #{bidResult}
and a.ict_profit>= #{minMll}
and a.ict_profit <= #{maxMll}
and a.open_bid_time >= #{startTime}
and a.open_bid_time <= #{endTime}
and c.unicom_type in
#{item}
order by a.project_name asc
